CREATE TABLE `sys_ureport_file`
(
    `id`          bigint   NOT NULL COMMENT '主键',
    `name`        varchar(100)      DEFAULT NULL COMMENT '文件名',
    `file_name`   varchar(255)      DEFAULT NULL COMMENT '下载文件名称',
    `content`     longblob COMMENT '文件数据',
    `create_by`   varchar(32)       DEFAULT NULL COMMENT '创建人',
    `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `update_by`   varchar(32)       DEFAULT NULL COMMENT '修改人',
    `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
    `deleted`     tinyint(1)        DEFAULT '0' COMMENT '逻辑删除: 1-已删除 0-未删除',
    PRIMARY KEY (`id`)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4 COMMENT ='报表文件表';

